const text = $json.text || $json.content || $json.input;
if (!text) throw new Error('Missing text/content/input field');
return [{ json: { text } }];

const stats = $json.stats || {};
const topWords = $json.top_words || [];
const sentiment = $json.sentiment_label || 'neutral';
const score = $json.sentiment_score || 0;

// SEO recommendations
const recommendations = [];
if (stats.words < 300) recommendations.push('Content too short for SEO (target 300+ words)');
if (stats.sentences < 5) recommendations.push('Add more sentences for readability');
if (topWords.length < 5) recommendations.push('Low keyword diversity - add related terms');
if (sentiment === 'negative') recommendations.push('Negative sentiment - consider reframing');

// Top keyword for SEO
const primaryKeyword = topWords[0]?.word || 'none';
const keywordDensity = topWords[0] ? (topWords[0].count / stats.words * 100).toFixed(1) : 0;

return [{
  json: {
    stats,
    top_keywords: topWords.slice(0, 5),
    primary_keyword: primaryKeyword,
    keyword_density_pct: parseFloat(keywordDensity),
    sentiment: { label: sentiment, score },
    seo: {
      word_count_ok: stats.words >= 300,
      reading_time_min: stats.reading_time_min,
      recommendations
    },
    analyzed_at: new Date().toISOString()
  }
}];
